class Solution {
public:
    bool match(ListNode* listNode, TreeNode* treeNode) {
        if (!listNode) return true;
        if (!treeNode) return false;
        if (listNode->val != treeNode->val) return false;
        return match(listNode->next, treeNode->left) || match(listNode->next, treeNode->right);
    }
    bool isSubPath(ListNode* head, TreeNode* root) {
        if (!root) return false;
        return match(head, root) || isSubPath(head, root->left) || isSubPath(head, root->right);
    }
};

class Solution {
    private boolean match(ListNode listNode, TreeNode treeNode) {
        if (listNode == null) return true;
        if (treeNode == null) return false;
        if (listNode.val != treeNode.val) return false;
        return match(listNode.next, treeNode.left) || match(listNode.next, treeNode.right);
    }
    public boolean isSubPath(ListNode head, TreeNode root) {
        if (root == null) return false;
        return match(head, root) || isSubPath(head, root.left) || isSubPath(head, root.right);
    }
}

var isSubPath = function(head, root) {
    const match = (listNode, treeNode) => {
        if (!listNode) return true;
        if (!treeNode) return false;
        if (listNode.val !== treeNode.val) return false;
        return match(listNode.next, treeNode.left) || match(listNode.next, treeNode.right);
    };
    if (!root) return false;
    return match(head, root) || isSubPath(head, root.left) || isSubPath(head, root.right);
};
